316	        {
317	            let tries = if left == 1 { "try" } else { "tries" };
318	            return refuse(
319	                403,
320	                "WrongPin",
321	                &format!("wrong PIN; {left} {tries} left this minute"),
322	            );
323	        }
324	        self.issued(board_id, &lock, true)
325	    }
326	
327	    async fn set_pin(&self, mut req: Request, board_id: &str) -> Result<Response> {
328	        let pass = req.headers().get(PASS_HEADER)?;
329	        let lock = self.lock.lock().map_err(Error::RustError)?;
330	        if let Some(refused) = self.check_pass(board_id, &lock, pass.as_deref())? {
331	            return Ok(refused);
332	        }
333	        let Ok(body) = req.json::<PinBody>().await else {
334	            return refuse(
335	                400,
336	                "InvalidPin",
337	                "send {\"pin\": \"<6 digits>\"} or an empty pin",
338	            );
339	        };
340	        if body.pin.is_empty() {
341	            self.lock.set_pin_hash("").map_err(Error::RustError)?;
342	            return Response::from_json(&json!({ "pinSet": false }));
343	        }
344	        if let Err(reason) = pin::check_pin(&body.pin) {
345	            return refuse(400, "InvalidPin", &reason);
346	        }
347	        if self.pass_secret().is_none() {
348	            return Self::missing_secret();
349	        }
350	        let hash = pin::hash_pin(&body.pin).await.map_err(Error::RustError)?;
351	        let lock = self
352	            .lock
353	            .set_pin_hash(&hash.encode())
354	            .map_err(Error::RustError)?;
355	        for ws in self.state.get_websockets() {
356	            ws.close(Some(PIN_CHANGED), Some("the board PIN changed"))?;
357	        }
358	        self.issued(board_id, &lock, true)
359	    }
360	
361	    fn pin_state(&self) -> Result<Response> {
362	        let lock = self.lock.lock().map_err(Error::RustError)?;
363	        Response::from_json(&json!({ "pinSet": lock.is_locked() }))
364	    }
365	
366	    fn session(ws: &WebSocket) -> Result<Session> {
367	        Ok(ws.deserialize_attachment()?.unwrap_or_default())
368	    }
369	
370	    fn deliver(&self, sender: &WebSocket, outgoing: Vec<board::Outgoing>) -> Result<()> {
371	        if outgoing.is_empty() {
372	            return Ok(());
373	        }
374	        let sockets = self.state.get_websockets();
375	        for out in outgoing {
376	            let bytes = out.frame.encode();
377	            for ws in &sockets {
378	                if out.route.reaches(ws == sender, &Self::session(ws)?) {
379	                    ws.send_with_bytes(&bytes)?;
380	                }
381	            }
382	        }
383	        Ok(())
384	    }
385	
386	    fn reject(ws: &WebSocket, tile_key: String, reason: String) -> Result<()> {
387	        let frame = Frame::new(tile_key, FrameKind::Reject, reason.into_bytes());
388	        ws.send_with_bytes(frame.encode())
389	    }
390	
391	    fn leave(&self, ws: &WebSocket) -> Result<()> {
392	        let session = Self::session(ws)?;
393	        let outgoing = self
394	            .board
395	            .borrow_mut()
396	            .close(&session)
397	            .map_err(Error::RustError)?;
398	        self.deliver(ws, outgoing)
399	    }
400	
401	    async fn arm_flush(&self) -> Result<()> {
402	        if self.flush_armed.get() || !self.board.borrow().has_dirty() {
403	            return Ok(());
404	        }
405	        self.flush_armed.set(true);
406	        let armed = self.state.storage().set_alarm(FLUSH_DELAY).await;
407	        if armed.is_err() {
408	            self.flush_armed.set(false);
409	        }
410	        armed
411	    }
412	}
