414	impl DurableObject for Board {
415	    fn new(state: State, env: Env) -> Self {
416	        let store = SqlTileStore::new(state.storage().sql());
417	        let lock = SqlLockStore::new(state.storage().sql());
418	        Board {
419	            state,
420	            env,
421	            lock,
422	            board: RefCell::new(BoardSync::new(|| Date::now().as_millis(), store)),
423	            flush_armed: Cell::new(false),
424	        }
425	    }
426	
427	    async fn fetch(&self, req: Request) -> Result<Response> {
428	        let url = req.url()?;
429	        let Some((board_id, endpoint)) = board_route(url.path()) else {
430	            return Response::error("expected /api/boards/{boardId}/ws, /join or /pin", 404);
431	        };
432	        let board_id = board_id.to_owned();
433	        match (endpoint, req.method()) {
434	            (Endpoint::Socket, _) => self.upgrade(req, &board_id).await,
435	            (Endpoint::Join, Method::Post) => self.join(req, &board_id).await,
436	            (Endpoint::Pin, Method::Post) => self.set_pin(req, &board_id).await,
437	            (Endpoint::Pin, Method::Get) => self.pin_state(),
438	            _ => Response::error("method not allowed", 405),
439	        }
440	    }
441	
442	    async fn websocket_message(
443	        &self,
444	        ws: WebSocket,
445	        message: WebSocketIncomingMessage,
446	    ) -> Result<()> {
447	        let WebSocketIncomingMessage::Binary(bytes) = message else {
448	            return ws.close(Some(1003), Some("frames are binary CBOR"));
449	        };
450	        let frame = match Frame::decode(&bytes) {
451	            Ok(frame) => frame,
452	            Err(reason) => return ws.close(Some(1007), Some(reason)),
453	        };
454	        let tile_key = frame.tile_key.clone();
455	        let mut session = Self::session(&ws)?;
456	        let result = self.board.borrow_mut().receive(&mut session, frame);
457	        match result {
458	            Ok(outgoing) => {
459	                ws.serialize_attachment(&session)?;
460	                self.deliver(&ws, outgoing)?;
461	                self.arm_flush().await
462	            }
463	            Err(reason) => Self::reject(&ws, tile_key, reason),
464	        }
465	    }
466	
467	    async fn websocket_close(
468	        &self,
469	        ws: WebSocket,
470	        _code: usize,
471	        _reason: String,
472	        _was_clean: bool,
473	    ) -> Result<()> {
474	        self.leave(&ws)
475	    }
476	
477	    async fn websocket_error(&self, ws: WebSocket, _error: Error) -> Result<()> {
478	        self.leave(&ws)
479	    }
480	
481	    async fn alarm(&self) -> Result<Response> {
482	        self.flush_armed.set(false);
483	        let mut board = self.board.borrow_mut();
484	        let flushed = board.flush().map_err(Error::RustError)?;
485	        board.evict_idle(IDLE_MS);
