116	impl<S: BoardIndexStore> UserBoards<S> {
117	    pub fn new(store: S) -> Self {
118	        UserBoards { store }
119	    }
120	
121	    fn purge(&self, now_ms: u64) -> Result<(), String> {
122	        self.store
123	            .purge_removed_before(now_ms.saturating_sub(TOMBSTONE_MS))
124	    }
125	
126	    pub fn list(&self, now_ms: u64) -> Result<Vec<MyBoard>, String> {
127	        self.purge(now_ms)?;
128	        let mut boards = self.store.all()?;
129	        boards.sort_by(|a, b| {
130	            b.last_opened
131	                .cmp(&a.last_opened)
132	                .then_with(|| a.board_id.cmp(&b.board_id))
133	        });
134	        Ok(boards)
135	    }
136	
137	    pub fn upsert(
138	        &self,
139	        board_id: &str,
140	        patch: BoardPatch,
141	        now_ms: u64,
142	    ) -> Result<Result<MyBoard, Refusal>, String> {
143	        if let Err(refusal) = check(&patch) {
144	            return Ok(Err(refusal));
145	        }
146	        self.purge(now_ms)?;
147	        let existing = self.store.get(board_id)?;
148	        let last_opened = match (&existing, patch.last_opened) {
149	            (Some(old), Some(given)) => old.last_opened.max(given),
150	            (Some(old), None) => old.last_opened,
151	            (None, Some(given)) => given,
152	            (None, None) => now_ms,
153	        };
154	        let removed_at = match (&existing, patch.last_opened) {
155	            (Some(old), Some(given)) if given > old.removed_at => 0,
156	            (Some(old), _) => old.removed_at,
157	            (None, _) => 0,
158	        };
159	        let board = MyBoard {
160	            board_id: board_id.to_owned(),
161	            name: patch
162	                .name
163	                .or_else(|| existing.as_ref().map(|old| old.name.clone()))
164	                .unwrap_or_else(|| board_id.to_owned()),
165	            last_opened,
166	            thumbnail: patch
167	                .thumbnail
168	                .or_else(|| existing.map(|old| old.thumbnail))
169	                .unwrap_or_default(),
170	            removed_at,
171	        };
172	        self.store.put(&board)?;
173	        let mut ages = self.store.ages()?;
174	        ages.sort_by(newest_first);
175	        for (evicted, _) in ages.iter().skip(MAX_BOARDS) {
176	            self.store.delete(evicted)?;
177	        }
178	        Ok(Ok(board))
179	    }
180	
181	    pub fn remove(&self, board_id: &str, now_ms: u64) -> Result<(), String> {
182	        self.purge(now_ms)?;
183	        let existing = self.store.get(board_id)?;
184	        let tombstone = MyBoard {
185	            board_id: board_id.to_owned(),
186	            name: existing
187	                .as_ref()
188	                .map_or_else(|| board_id.to_owned(), |old| old.name.clone()),
189	            last_opened: existing.as_ref().map_or(0, |old| old.last_opened),
190	            thumbnail: String::new(),
191	            removed_at: now_ms.max(existing.map_or(0, |old| old.removed_at)),
192	        };
193	        self.store.put(&tombstone)
194	    }
195	}
